mapper.select:
select distinct u.id, u.dept_id, u.login_name, u.username, u.user_type, u.email, u.phone, u.sex, u.avatar, u.status, u.login_ip, u.login_date, u.create_time, u.create_by, u.update_time, u.update_by
from sys_user u
inner join sys_dept d on u.dept_id = d.id
left join sys_user_role ur on ur.user_id = u.id
where u.del_flag = 0

    and (d.id = #{req.deptId} or d.ancestors LIKE CONCAT('%,', #{req.deptId}, ',%'))


    and u.status = #{req.status}


    and u.login_name like concat('%', #{req.loginName}, '%')


    and u.username like concat('%', #{req.username}, '%')


    and u.phone like concat('%', #{req.phone}, '%')


    and u.create_time >= #{req.startCreateTime}


    and u.create_time <= #{req.endCreateTime}


    and ur.role_id = #{req.roleId}

select u.id, u.login_name, u.username, u.user_type, u.email, u.phone, u.sex, u.avatar, u.status, u.dept_id, u.tenant_id, d.dept_name from sys_user u
inner join sys_dept d on u.dept_id = d.id
where u.id = #{id}
